INSERT OR IGNORE INTO articles(slug,section,language,title,summary,body,sources_json,status,created_at,updated_at) VALUES
('who-is-naguib-mahfouz-ar','people','ar','نجيب محفوظ: من هو وما الذي ميّز تجربته؟','ملف تعريفي منظم عن الأديب المصري، أعماله ومحطات حياته ومكانته الأدبية.','هذا ملف معرفي تمهيدي عن نجيب محفوظ. يجمع السيرة والأعمال والجوائز في صفحة واحدة، مع فصل المعلومات المؤكدة عن التفسير النقدي. يمكن توسيع الملف لاحقًا بإضافة خط زمني وأعمال ومصادر إضافية.','[{"title":"Naguib Mahfouz","publisher":"Nobel Prize","url":"https://www.nobelprize.org/prizes/literature/1988/mahfouz/facts/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('who-is-naguib-mahfouz-en','people','en','Naguib Mahfouz: life, work and legacy','A structured introduction to the Egyptian novelist, his works, milestones and literary legacy.','This is a verified introductory profile of Naguib Mahfouz. It separates biographical facts from literary interpretation and provides a starting point for a deeper person page with a timeline, works and additional evidence.','[{"title":"Naguib Mahfouz","publisher":"Nobel Prize","url":"https://www.nobelprize.org/prizes/literature/1988/mahfouz/facts/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('what-is-inflation-ar','economy','ar','ما هو التضخم؟ شرح مبسط ومتكامل','تعريف التضخم، كيف يُقاس، لماذا يحدث، وكيف يؤثر في القوة الشرائية.','التضخم هو ارتفاع عام ومستمر نسبيًا في مستوى أسعار السلع والخدمات، ما يعني أن وحدة النقد تشتري كمية أقل من السلع عندما ترتفع الأسعار. لفهم التضخم بدقة يجب النظر إلى معدل التغير في مؤشر الأسعار، وليس إلى ارتفاع سعر سلعة واحدة فقط.','[{"title":"Inflation","publisher":"International Monetary Fund","url":"https://www.imf.org/en/Topics/inflation"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('what-is-inflation-en','economy','en','What is inflation? A clear explanation','What inflation means, how it is measured, why it happens and how it affects purchasing power.','Inflation is a sustained increase in the general level of prices for goods and services. A single price increase is not enough to describe economy-wide inflation; the rate is assessed using broad price measures over time.','[{"title":"Inflation","publisher":"International Monetary Fund","url":"https://www.imf.org/en/Topics/inflation"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('how-ai-works-ar','technology','ar','كيف يعمل الذكاء الاصطناعي التوليدي؟','شرح مبسط من البيانات والتدريب إلى التنبؤ بالنص أو الصورة، مع حدود الدقة.','الذكاء الاصطناعي التوليدي يعتمد على نماذج تتعلم أنماطًا من بيانات تدريب ثم تنتج مخرجات جديدة بناءً على المدخلات. جودة النتيجة تعتمد على النموذج والبيانات والسياق، لذلك لا ينبغي اعتبار كل مخرجات النموذج حقيقة دون تحقق.','[{"title":"Generative AI","publisher":"NIST","url":"https://www.nist.gov/artificial-intelligence"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('how-ai-works-en','technology','en','How generative AI works','From training data and learned patterns to generated text or images, including important limits.','Generative AI models learn patterns from training data and produce new outputs conditioned on a prompt or other input. Their outputs can be useful while still containing errors, so important claims should be checked against reliable evidence.','[{"title":"Artificial Intelligence","publisher":"NIST","url":"https://www.nist.gov/artificial-intelligence"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('how-to-debug-web-ar','guides','ar','كيف تبدأ في إصلاح مشكلة في موقع ويب؟','من وصف المشكلة إلى عزل السبب واختبار الإصلاح دون كسر أجزاء أخرى.','ابدأ بإعادة إنتاج المشكلة، ثم سجل رسالة الخطأ والصفحة والطلب المتأثر. بعد ذلك اعزل السبب المحتمل، عدّل أصغر جزء ممكن، وشغّل الاختبارات قبل النشر. بعد النشر اختبر المسار الحقيقي مرة أخرى وسجل النتيجة.','[{"title":"Debugging","publisher":"MDN Web Docs","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('how-to-debug-web-en','guides','en','How to start debugging a website','A safe workflow for reproducing, isolating, fixing and retesting a web problem.','Reproduce the failure, capture the exact error and affected request, isolate the smallest likely cause, make a reversible change, run tests, then verify the production path after deployment. Keep evidence for each step rather than guessing.','[{"title":"Web development guides","publisher":"MDN Web Docs","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('why-sky-blue-ar','science','ar','لماذا السماء زرقاء؟','شرح مبسط لتشتت الضوء في الغلاف الجوي ولماذا يغلب اللون الأزرق نهارًا.','ضوء الشمس يحتوي أطوالًا موجية متعددة. جزيئات الغلاف الجوي تشتت الأطوال الموجية الأقصر بكفاءة أكبر من الأطول، لذلك يصل الضوء الأزرق المتشتت من اتجاهات كثيرة إلى أعيننا أثناء النهار.','[{"title":"Why Is the Sky Blue?","publisher":"NASA","url":"https://science.nasa.gov/earth/earth-observatory/why-is-the-sky-blue/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('why-sky-blue-en','science','en','Why is the sky blue?','A clear explanation of atmospheric scattering and the blue appearance of the daytime sky.','Sunlight contains many wavelengths. Molecules in the atmosphere scatter shorter wavelengths more strongly than longer wavelengths, so scattered blue light reaches our eyes from many directions during the day.','[{"title":"Why Is the Sky Blue?","publisher":"NASA","url":"https://science.nasa.gov/earth/earth-observatory/why-is-the-sky-blue/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('what-is-public-health-ar','health','ar','كيف نقيّم المعلومة الصحية؟','قواعد عملية للتمييز بين المعلومة الطبية الموثوقة والادعاء غير المدعوم.','المعلومة الصحية الجيدة توضح الدليل وحدوده، وتفرق بين دراسة واحدة والإجماع العلمي، وتذكر متى يلزم الرجوع إلى مختص. لا ينبغي استخدام صفحة معلومات عامة بدل التشخيص أو العلاج الشخصي.','[{"title":"Health Topics","publisher":"World Health Organization","url":"https://www.who.int/health-topics"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('what-is-public-health-en','health','en','How to evaluate health information','Practical rules for distinguishing reliable health evidence from unsupported claims.','Reliable health information states what the evidence shows and what it does not show. It distinguishes a single study from a broader body of evidence and makes clear when personal medical advice requires a qualified professional.','[{"title":"Health Topics","publisher":"World Health Organization","url":"https://www.who.int/health-topics"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('world-war-two-overview-ar','history-culture','ar','الحرب العالمية الثانية: خط زمني مختصر','مدخل منظم إلى أهم مراحل الحرب وأطرافها ونهايتها.','بدأت الحرب العالمية الثانية في أوروبا عام 1939 ثم اتسع نطاقها عالميًا. من أبرز محطاتها توسع دول المحور، دخول الولايات المتحدة بعد هجوم بيرل هاربر، تقدم الحلفاء، وإنهاء الحرب في أوروبا وآسيا عام 1945.','[{"title":"World War II","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/World-War-II"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('world-war-two-overview-en','history-culture','en','World War II: a concise timeline','A structured introduction to the major phases, participants and end of the Second World War.','World War II began in Europe in 1939 and expanded into a global conflict. Major phases included Axis expansion, the United States entering the war after Pearl Harbor, Allied advances, and the end of the war in Europe and Asia in 1945.','[{"title":"World War II","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/World-War-II"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('what-is-a-news-story-ar','topics','ar','كيف نفهم خبرًا واحدًا من أكثر من مصدر؟','من headline واحد إلى صورة كاملة: الحدث، التوقيت، المصادر، الخلافات والسياق.','الخبر الجيد لا يكتفي بعنوان. يجب معرفة ما الذي حدث، متى، من قال ماذا، وما الأدلة المستقلة المتاحة. إذا اختلفت المصادر، يجب عرض الاختلاف بدل إخفائه أو اختيار رواية واحدة بلا تفسير.','[{"title":"Journalism Handbook","publisher":"UNESCO","url":"https://www.unesco.org/en/communication-information"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z'),
('what-is-a-news-story-en','topics','en','How to understand one news event from multiple sources','Move beyond a headline by separating the event, timing, sources, disagreements and context.','A strong news understanding starts with what happened, when it happened, who reported each claim and what independent evidence exists. When sources disagree, the disagreement should be shown and explained rather than hidden.','[{"title":"Communication and Information","publisher":"UNESCO","url":"https://www.unesco.org/en/communication-information"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z');